package tracequery

import (
	"fmt"
	"math"
	"regexp"
	"sort"
	"strings"
)

// FrameCatalogMatch compares candidates generated by the baseline catalog.
// A ranked sample has no cross-capture frame identity guarantee.
type FrameCatalogMatch struct {
	Status     string                `json:"status"`
	SelectedID string                `json:"selected_id,omitempty"`
	Target     FrameCatalogEntry     `json:"target"`
	Candidates []FrameMatchCandidate `json:"candidates"`
	Considered int                   `json:"considered"`
}

type FrameMatchCandidate struct {
	Frame        FrameCatalogEntry  `json:"frame"`
	Score        float64            `json:"score"`
	Evidence     map[string]float64 `json:"evidence"`
	WindowAgrees bool               `json:"window_agrees"`
}

var framePointDynamicArgument = regexp.MustCompile(`@[0-9a-fA-F]+|0x[0-9a-fA-F]+|\b\d{4,}\b`)

var frameMatchAnchorNames = []string{
	"bindApplication", "activityResume", "activityStart", "MSG_WINDOW_FOCUS_CHANGED",
	"MSG_DISPATCH_APP_VISIBILITY", "handleLaunchActivity", "deliverInputEvent",
}

type frameMatchProfile struct {
	points  map[string]bool
	ordered []string
}

type frameMatchObservation struct {
	frame     FrameCatalogEntry
	main      frameMatchProfile
	render    frameMatchProfile
	windows   map[string]bool
	durations map[string]float64
}

type frameMatchAnchor struct {
	targetNS, baselineNS uint64
	unique               bool
}

// MatchFrameCatalog selects a reference by comparing the target with the
// complete baseline directory. targetVsync belongs to the target capture.
func MatchFrameCatalog(target, baseline FrameCatalog, targetVsync uint64, limit int) (FrameCatalogMatch, error) {
	return matchFrameCatalog(target, baseline, targetVsync, limit, "")
}

func matchFrameCatalog(target, baseline FrameCatalog, targetVsync uint64, limit int, baselineVideoPath string) (FrameCatalogMatch, error) {
	focus, err := FrameCatalogTarget(target, targetVsync)
	if err != nil {
		return FrameCatalogMatch{}, err
	}
	targetLine, targetTID := focus.StartLine, focus.TID
	result := FrameCatalogMatch{Status: "unresolved"}
	counts := make(map[string]int)
	left, leftAnchors := frameMatchObservations(target, targetTID, counts)
	// A source-local selector can match more than one emitter name occurrence;
	// compare each baseline emitter in its own chronological sequence.
	var baselineTIDs []int
	seen := make(map[int]bool)
	for _, frame := range baseline.Frames {
		if !seen[frame.TID] {
			baselineTIDs = append(baselineTIDs, frame.TID)
			seen[frame.TID] = true
		}
	}
	targetIndex := 0
	for i, row := range left {
		if row.frame.StartLine == targetLine {
			targetIndex = i
			break
		}
	}
	result.Target = left[targetIndex].frame
	targetUpdate := frameWindowUpdates(target, targetTID)[targetLine]
	targetTrajectory := frameMatchTrajectories(left, targetIndex)
	targetEpisode := frameMatchEpisode(frameMatchPointGroups(target, targetTID), result.Target.StartNS)
	type baselineLane struct {
		rows    []frameMatchObservation
		anchors map[string][]uint64
		groups  []frameMatchPointGroup
	}
	var lanes []baselineLane
	for _, tid := range baselineTIDs {
		rows, anchors := frameMatchObservations(baseline, tid, counts)
		var groups []frameMatchPointGroup
		if len(targetEpisode) >= 3 {
			groups = frameMatchPointGroups(baseline, tid)
		}
		lanes = append(lanes, baselineLane{rows, anchors, groups})
	}
	weights := make(map[string]float64, len(counts))
	for point, count := range counts {
		weights[point] = .05 + math.Log(float64(len(left)+len(baseline.Frames)+1)/float64(count+1))
	}
	renderComparable := false
	if len(left[targetIndex].render.ordered) > 0 {
		for _, lane := range lanes {
			for _, row := range lane.rows {
				renderComparable = renderComparable || len(row.render.ordered) > 0
			}
		}
	}
	windowUpdateMatched := false
	var leftCadence float64
	if baselineVideoPath != "" {
		leftCadence = frameMatchNominalCadence(left)
	}
	for _, lane := range lanes {
		anchors := pairFrameMatchAnchors(leftAnchors, lane.anchors)
		var rightCadence float64
		if baselineVideoPath != "" {
			rightCadence = frameMatchNominalCadence(lane.rows)
		}
		var windowUpdates map[int]frameWindowUpdate
		if targetUpdate.generation != 0 {
			windowUpdates = frameWindowUpdates(baseline, lane.rows[0].frame.TID)
		}
		for j, candidate := range lane.rows {
			agrees, differs := frameMatchWindows(left[targetIndex].windows, candidate.windows)
			if differs {
				continue
			}
			evidence := frameMatchEvidence(left, lane.rows, targetIndex, j, weights, anchors, leftCadence, rightCadence)
			if update := windowUpdates[candidate.frame.StartLine]; update.generation != 0 &&
				update.window == targetUpdate.window && update.generation == targetUpdate.generation {
				if update.parameters == targetUpdate.parameters {
					evidence["window_update_role"] = 1
					windowUpdateMatched = true
				} else {
					evidence["window_update_role_conflict"] = 1
				}
			}
			if len(targetTrajectory) != 0 {
				if affinity, ok := frameMatchTrajectorySimilarity(targetTrajectory, frameMatchTrajectories(lane.rows, j)); ok {
					evidence["trajectory"] = affinity
				}
			}
			if len(lane.groups) != 0 {
				if affinity, ok := frameMatchEpisodeSimilarity(targetEpisode, frameMatchEpisode(lane.groups, candidate.frame.StartNS)); ok {
					evidence["point_episode"] = affinity
				}
			}
			score := .25*evidence["before_gaps"] + .10*evidence["after_gaps"] +
				.20*math.Max(evidence["incoming_gap"], evidence["first_observed_pair"]) + .10*evidence["local_points"] +
				.15*evidence["neighbor_points"] + .20*evidence["anchor_position"]
			if renderComparable {
				score *= .8
				if len(candidate.render.ordered) != 0 {
					evidence["render_points"] = frameMatchPointSimilarity(left[targetIndex].render, candidate.render, weights)
					score += .2 * evidence["render_points"]
				}
			}
			result.Candidates = append(result.Candidates, FrameMatchCandidate{
				Frame: candidate.frame, Score: score, Evidence: evidence, WindowAgrees: agrees,
			})
		}
	}
	applyFrameMatchTrajectorySupport(result.Candidates)
	applyFrameMatchEpisodeSupport(result.Candidates)
	if windowUpdateMatched {
		for i := range result.Candidates {
			c := &result.Candidates[i]
			c.Score = .6*c.Score + .4*c.Evidence["window_update_role"]
			// A different observed update in the same window lifecycle is
			// weaker evidence than a candidate lacking the relayout marker.
			if c.Evidence["window_update_role_conflict"] != 0 {
				c.Score *= .6
			}
		}
	}
	sort.SliceStable(result.Candidates, func(i, j int) bool {
		return result.Candidates[i].Score > result.Candidates[j].Score
	})
	if len(baselineTIDs) == 1 && len(result.Candidates) > 1 {
		chain := frameMatchLandmarks(target, baseline, targetTID, baselineTIDs[0])
		rerankByFrameMatchLandmarks(result.Candidates, chain, result.Target.StartNS)
	}
	result.Considered = len(result.Candidates)
	if baselineVideoPath != "" {
		// Keep the comparison on the already observed baseline output path.
		// The rest of the ordering remains available as alternative evidence.
		for i, candidate := range result.Candidates[:min(10, len(result.Candidates))] {
			if candidate.Frame.VideoOutputPath != baselineVideoPath {
				continue
			}
			copy(result.Candidates[1:i+1], result.Candidates[:i])
			candidate.Evidence["mixed_video_output_path"] = 1
			result.Candidates[0] = candidate
			break
		}
		if len(result.Candidates) == 0 || result.Candidates[0].Evidence["mixed_video_output_path"] == 0 {
			return result, nil
		}
	}
	if n := len(result.Candidates); n > 0 {
		best := result.Candidates[0]
		// A usable reference needs shared work as well as a distinguishing
		// ordering signal. Applying the same evidence never proves identity.
		if best.Evidence["local_points"] > 0 &&
			(best.Evidence["before_gaps"] > 0 || best.Evidence["anchor_position"] > 0) &&
			(n == 1 || best.Score > result.Candidates[1].Score) {
			result.Status = "reference_only"
			result.SelectedID = best.Frame.ID
		}
		if baselineVideoPath == "" && result.SelectedID != "" && result.Target.VideoOutputPath != "" &&
			best.Frame.VideoOutputPath != "" && best.Frame.VideoOutputPath != result.Target.VideoOutputPath {
			// A long gap is less comparable when one video is composed into
			// the application window and the other uses a separate surface.
			alternate, err := matchFrameCatalog(target, baseline, targetVsync, limit, best.Frame.VideoOutputPath)
			if err == nil && alternate.SelectedID != "" {
				return alternate, nil
			}
		}
		if baselineVideoPath == "" && result.SelectedID != "" {
			rerankByFrameHostComposition(result.Target, result.Candidates)
			result.SelectedID = result.Candidates[0].Frame.ID
		}
		limit = ViewCapacityFor(ViewFrameCatalog).ClampLimit(limit)
		result.Candidates = result.Candidates[:min(n, limit)]
	}
	return result, nil
}

func FrameCatalogTarget(catalog FrameCatalog, vsync uint64) (FrameCatalogEntry, error) {
	var found FrameCatalogEntry
	for _, frame := range catalog.Frames {
		if frame.Vsync != vsync {
			continue
		}
		if found.StartLine != 0 {
			return FrameCatalogEntry{}, fmt.Errorf("target vsync %d is ambiguous; select its exact thread or a narrower target scope", vsync)
		}
		found = frame
	}
	if found.StartLine == 0 {
		return FrameCatalogEntry{}, fmt.Errorf("target vsync %d has no closed frame in the selected catalog", vsync)
	}
	return found, nil
}

func frameMatchObservations(catalog FrameCatalog, tid int, counts map[string]int) ([]frameMatchObservation, map[string][]uint64) {
	var rows []frameMatchObservation
	byLine := make(map[int]int)
	for _, frame := range catalog.Frames {
		if frame.TID == tid {
			byLine[frame.StartLine] = len(rows)
			rows = append(rows, frameMatchObservation{frame: frame, main: frameMatchProfile{points: map[string]bool{}}, windows: map[string]bool{}})
		}
	}
	anchors := make(map[string][]uint64)
	for _, span := range catalog.PointSpans {
		if span.Role == "render" {
			if i, ok := byLine[span.FrameLine]; ok {
				profile := &rows[i].render
				if profile.points == nil {
					profile.points = make(map[string]bool)
				}
				k := "render:" + frameMatchPoint(span.Name)
				if !profile.points[k] {
					profile.points[k] = true
					counts[k]++
				}
			}
			continue
		}
		if span.TID != tid {
			continue
		}
		k := frameMatchPoint(span.Name)
		for _, name := range frameMatchAnchorNames {
			if k != name {
				continue
			}
			times := anchors[k]
			if len(times) == 0 || span.StartNS > times[len(times)-1]+12_000_000 {
				anchors[k] = append(times, span.StartNS)
			}
			break
		}
		if i, ok := byLine[span.FrameLine]; ok {
			row := &rows[i]
			if !row.main.points[k] {
				counts[k]++
				row.main.points[k] = true
			}
			if window, ok := strings.CutPrefix(k, "draw["); ok {
				row.windows[window] = true
			}
			if span.EndNS > span.StartNS && k != "jank_marker" {
				if row.durations == nil {
					row.durations = make(map[string]float64)
				}
				ms := float64(span.EndNS-span.StartNS) / 1e6
				row.durations[k] = math.Max(row.durations[k], ms)
			}
		}
	}
	if len(rows) != 0 {
		anchors["first_observed_frame"] = []uint64{rows[0].frame.StartNS}
	}
	for i := range rows {
		row := &rows[i]
		if len(row.main.points) == 0 {
			for _, p := range row.frame.Points {
				k := frameMatchPoint(p)
				if !row.main.points[k] {
					row.main.points[k] = true
					counts[k]++
				}
				if window, ok := strings.CutPrefix(k, "draw["); ok {
					row.windows[window] = true
				}
			}
		}
		for _, profile := range []*frameMatchProfile{&row.main, &row.render} {
			for point := range profile.points {
				if point != "jank_marker" && point != "render:jank_marker" {
					profile.ordered = append(profile.ordered, point)
				}
			}
			sort.Strings(profile.ordered)
		}
	}
	return rows, anchors
}

func frameMatchPoint(name string) string {
	if window, initial, ok := frameWindowUpdateMarker(name); ok {
		if initial {
			return "relayoutWindow:initial[" + window + "]"
		}
		return "relayoutWindow:parameters[" + window + "]"
	}
	for _, anchor := range frameMatchAnchorNames {
		if strings.Contains(strings.ToLower(name), strings.ToLower(anchor)) {
			return anchor
		}
	}
	for _, role := range []string{"measure", "layout", "draw"} {
		if tail, ok := strings.CutPrefix(name, role+"-VRI["); ok {
			if window, _, closed := strings.Cut(tail, "]"); closed {
				return role + "[" + lastFrameMatchComponent(window) + "]"
			}
		}
	}
	if surface, ok := strings.CutPrefix(name, "DrawFrames setSurfaceName "); ok {
		_, activity, qualified := strings.Cut(surface, "/")
		if qualified {
			return "submit[" + lastFrameMatchComponent(activity) + "]"
		}
	}
	if strings.HasPrefix(name, "Choreographer#doFrame - resynced") {
		return "resync"
	}
	if strings.Contains(name, "jank_event_sync:") {
		return "jank_marker"
	}
	for _, p := range []string{"traversal", "postAndWait", "Record View#draw()", "TextureView#draw()", "relayoutWindow", "scheduleVsyncLocked", "ImageDecoder", "inflate"} {
		if strings.Contains(name, p) {
			return p
		}
	}
	return framePointDynamicArgument.ReplaceAllString(strings.TrimSpace(name), "#")
}

func lastFrameMatchComponent(name string) string {
	if i := strings.LastIndexByte(name, '.'); i >= 0 {
		return name[i+1:]
	}
	return name
}

func frameMatchWindows(a, b map[string]bool) (agrees, differs bool) {
	for window := range a {
		if b[window] {
			return true, false
		}
	}
	return false, len(a) != 0 && len(b) != 0
}

func pairFrameMatchAnchors(a, b map[string][]uint64) []frameMatchAnchor {
	var pairs []frameMatchAnchor
	for name, left := range a {
		right := b[name]
		if len(left) != len(right) {
			continue
		}
		for i := range left {
			pairs = append(pairs, frameMatchAnchor{left[i], right[i], len(left) == 1 && name != "first_observed_frame"})
		}
	}
	return pairs
}

func frameMatchNominalCadence(rows []frameMatchObservation) float64 {
	gaps := make([]float64, 0, len(rows))
	for i := 1; i < len(rows); i++ {
		if rows[i].frame.StartNS > rows[i-1].frame.StartNS {
			gaps = append(gaps, float64(rows[i].frame.StartNS-rows[i-1].frame.StartNS)/1e6)
		}
	}
	if len(gaps) == 0 {
		return 0
	}
	sort.Float64s(gaps)
	return gaps[(len(gaps)-1)/2]
}

func frameMatchEvidence(a, b []frameMatchObservation, i, j int, weights map[string]float64, anchors []frameMatchAnchor, leftCadence, rightCadence float64) map[string]float64 {
	result := map[string]float64{"local_points": frameMatchPointSimilarity(a[i].main, b[j].main, weights)}
	gap := func(rows []frameMatchObservation, at int) (float64, bool) {
		if at <= 0 || at >= len(rows) || rows[at].frame.StartNS < rows[at-1].frame.StartNS {
			return 0, false
		}
		return float64(rows[at].frame.StartNS-rows[at-1].frame.StartNS) / 1e6, true
	}
	var before, after, neighbors float64
	var beforeN, afterN, neighborN int
	for offset := -3; offset <= 3; offset++ {
		x, y := i+offset, j+offset
		if x < 0 || x >= len(a) || y < 0 || y >= len(b) {
			continue
		}
		if offset != 0 {
			neighbors += frameMatchPointSimilarity(a[x].main, b[y].main, weights)
			neighborN++
		}
		if offset == -3 {
			continue
		}
		p, okP := gap(a, x)
		q, okQ := gap(b, y)
		if !okP || !okQ {
			continue
		}
		if leftCadence > 0 && p > 2*leftCadence || rightCadence > 0 && q > 2*rightCadence {
			continue
		}
		similarity := math.Min(1+p, 1+q) / math.Max(1+p, 1+q)
		if offset <= 0 {
			before += similarity
			beforeN++
		} else {
			after += similarity
			afterN++
		}
		if offset == 0 {
			result["incoming_gap"] = similarity
		}
	}
	if i == 0 && j == 0 {
		result["first_observed_pair"] = 1
	}
	if beforeN != 0 {
		result["before_gaps"] = before / float64(beforeN)
	}
	if afterN != 0 {
		result["after_gaps"] = after / float64(afterN)
	}
	if neighborN != 0 {
		result["neighbor_points"] = neighbors / float64(neighborN)
	}
	for _, pair := range anchors {
		p := (float64(a[i].frame.StartNS) - float64(pair.targetNS)) / 1e6
		q := (float64(b[j].frame.StartNS) - float64(pair.baselineNS)) / 1e6
		if (p < 0) != (q < 0) {
			continue
		}
		v := math.Exp(-math.Abs(p-q) / (40 + .35*math.Abs(p)))
		if !pair.unique {
			v *= .6
		}
		result["anchor_position"] = math.Max(result["anchor_position"], v)
	}
	return result
}

func frameMatchPointSimilarity(a, b frameMatchProfile, weights map[string]float64) float64 {
	var shared, total float64
	for _, p := range a.ordered {
		total += weights[p]
		if b.points[p] {
			shared += weights[p]
		}
	}
	for _, p := range b.ordered {
		if !a.points[p] {
			total += weights[p]
		}
	}
	if total == 0 {
		return 0
	}
	return shared / total
}
